+    }
+
+    button:hover {
+      filter: brightness(1.06);
+      box-shadow: 0 18px 40px rgba(14, 165, 233, 0.34);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 3px solid rgba(186, 230, 253, 0.8);
+      outline-offset: 3px;
+    }
+
+    .success-message {
+      min-height: 1.5rem;
+      margin: 18px 0 0;
+      color: #86efac;
+      font-weight: 700;
+      text-align: center;
+    }
+
+    .success-message:empty {
+      display: none;
+    }
+
+    @media (max-width: 520px) {
+      .support-card {
+        padding: 28px 22px;
+        border-radius: 20px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="support-card" aria-labelledby="support-title">
+      <h1 id="support-title">Contact support</h1>
+      <p class="intro">Tell us how to reach you and our team will get back to you as soon as possible.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name</label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            placeholder="Alex Morgan"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address</label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            placeholder="alex@example.com"
+            required
+            aria-describedby="email-error"
+          >
+          <p class="error-message" id="email-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            placeholder="+1 555 123 4567"
+            aria-describedby="phone-helper phone-error"
+          >
+          <p class="helper-text" id="phone-helper">Expected format: country code followed by area code and number, for example +1 555 123 4567.</p>
+          <p class="error-message" id="phone-error" aria-live="polite"></p>
+        </div>
+
+        <button type="submit">Submit request</button>
+        <p class="success-message" id="success-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const successMessage = document.querySelector("#success-message");
+    const fields = {
+      fullName: {
+        input: document.querySelector("#full-name"),
+        error: document.querySelector("#full-name-error"),
+        validate(value) {
+          return value.trim() ? "" : "Full name is required.";
+        }
+      },
+      email: {
+        input: document.querySelector("#email"),
+        error: document.querySelector("#email-error"),
+        validate(value) {
+          if (!value.trim()) {
+            return "Email address is required.";
+          }
+
+          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
+            ? ""
+            : "Enter a valid email address.";
+        }
+      },
+      phone: {
+        input: document.querySelector("#phone"),
+        error: document.querySelector("#phone-error"),
+        validate(value) {
+          if (!value.trim()) {
+            return "";
+          }
+
+          return /^\+?[0-9\s().-]{7,20}$/.test(value.trim())
+            ? ""
+            : "Enter a phone number using digits, spaces, dashes, parentheses, and an optional leading +.";
+        }
+      }
+    };
+
+    function setError(field, message) {
+      field.error.textContent = message;
+      field.input.setAttribute("aria-invalid", message ? "true" : "false");
+    }
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      successMessage.textContent = "";
+
+      const invalidFields = Object.values(fields).filter((field) => {
+        const message = field.validate(field.input.value);
+        setError(field, message);
+        return Boolean(message);
+      });
+
+      if (invalidFields.length > 0) {
+        invalidFields[0].input.focus();
+        return;
+      }
+
+      form.reset();
+      Object.values(fields).forEach((field) => setError(field, ""));
+      successMessage.textContent = "Thanks! Your support request has been submitted.";
+    });
+
+    Object.values(fields).forEach((field) => {
+      field.input.addEventListener("input", () => {
+        if (field.input.getAttribute("aria-invalid") === "true") {
+          setError(field, field.validate(field.input.value));
+        }
+      });
+    });
+  </script>
