  <style>
    :root {
      color-scheme: dark;
      --bg: #080b12;
      --panel: #111827;
      --panel-border: #243044;
      --text: #f8fafc;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --accent-strong: #0ea5e9;
      --danger: #fb7185;
      --field: #0f172a;
      --field-border: #334155;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      background:
        radial-gradient(circle at top left, rgba(56, 189, 248, 0.18), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.14), transparent 30rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    main {
      width: min(100%, 520px);
    }

    .support-card {
      padding: 36px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.92));
      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(2rem, 5vw, 2.75rem);
      line-height: 1;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 0 0 30px;
      color: var(--muted);
      line-height: 1.6;
    }

    .form-field {
      margin-bottom: 20px;
    }

    label {
      display: block;
      margin-bottom: 8px;
      color: #dbeafe;
      font-weight: 700;
      letter-spacing: 0.01em;
    }

    input {
      width: 100%;
      border: 1px solid var(--field-border);
      border-radius: 14px;
      background: var(--field);
      color: var(--text);
      font: inherit;
      padding: 14px 16px;
      outline: none;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16);
      background: #111c31;
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
    }

    .helper-text {
      margin: 8px 0 0;
      color: var(--muted);
      font-size: 0.9rem;
      line-height: 1.4;
    }

    .error-message {
      min-height: 1.25rem;
      margin: 8px 0 0;
      color: var(--danger);
      font-size: 0.9rem;
      line-height: 1.4;
    }

    .error-message:empty {
      display: none;
    }

    button {
      width: 100%;
      margin-top: 8px;
      border: 0;
      border-radius: 14px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #03111f;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      padding: 15px 18px;
      box-shadow: 0 14px 32px rgba(14, 165, 233, 0.28);
      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
