 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #080b12;
       --panel: #111827;
       --panel-border: #243044;
       --text: #f8fafc;
       --muted: #94a3b8;
