       margin-bottom: 8px;
       color: #dbeafe;
       font-weight: 700;
       letter-spacing: 0.01em;
     }

     input {
       width: 100%;
       border: 1px solid var(--field-border);
       border-radius: 14px;
       background: var(--field);
       color: var(--text);
       font: inherit;
       padding: 14px 16px;
       outline: none;
       transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
     }

     input::placeholder {
       color: #64748b;
     }

     input:focus {
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16);
       background: #111c31;
     }

     input[aria-invalid="true"] {
       border-color: var(--danger);
     }

     .helper-text {
       margin: 8px 0 0;
       color: var(--muted);
       font-size: 0.9rem;
       line-height: 1.4;
     }

     .error-message {
       min-height: 1.25rem;
       margin: 8px 0 0;
       color: var(--danger);
       font-size: 0.9rem;
       line-height: 1.4;
     }

     .error-message:empty {
       display: none;
     }

     button {
       width: 100%;
       margin-top: 8px;
       border: 0;
       border-radius: 14px;
       background: linear-gradient(135deg, var(--accent), var(--accent-strong));
       color: #03111f;
       cursor: pointer;
       font: inherit;
       font-weight: 800;
       padding: 15px 18px;
       box-shadow: 0 14px 32px rgba(14, 165, 233, 0.28);
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
     }

     button:hover {
       filter: brightness(1.06);
       box-shadow: 0 18px 40px rgba(14, 165, 233, 0.34);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid rgba(186, 230, 253, 0.8);
